"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[93114],{54640(e,a,n){n.r(a),n.d(a,{assets:()=>c,contentTitle:()=>d,default:()=>u,frontMatter:()=>i,metadata:()=>o,toc:()=>l});const o=JSON.parse('{"id":"cursos/docker/modulos/redes-docker/cuestionario","title":"Cuestionario M06 \u2014 Redes en Docker","description":"Instrucci\xf3n: Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del","source":"@site/docs/cursos/docker/modulos/06-redes-docker/cuestionario.md","sourceDirName":"cursos/docker/modulos/06-redes-docker","slug":"/cursos/docker/modulos/redes-docker/cuestionario","permalink":"/sasf-temarios/cursos/docker/modulos/redes-docker/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/docker/modulos/redes-docker/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/docker/modulos/redes-docker/ejercicio"}}');var r=n(74848),s=n(28453);const i={sidebar_label:"Cuestionario"},d="Cuestionario M06 \u2014 Redes en Docker",c={},l=[{value:"1. [Investigar] \xbfC\xf3mo funciona exactamente la red overlay de Docker Swarm usando VXLAN? Describ\xed el encapsulamiento de paquetes y el rol del plano de control (gossip) vs plano de datos (VXLAN).",id:"1-investigar-c\xf3mo-funciona-exactamente-la-red-overlay-de-docker-swarm-usando-vxlan-describ\xed-el-encapsulamiento-de-paquetes-y-el-rol-del-plano-de-control-gossip-vs-plano-de-datos-vxlan",level:3},{value:"2. [Investigar] \xbfQu\xe9 es exactamente eBPF en el contexto de networking de contenedores y c\xf3mo Cilium lo usa para reemplazar kube-proxy? \xbfPor qu\xe9 iptables escala mal?",id:"2-investigar-qu\xe9-es-exactamente-ebpf-en-el-contexto-de-networking-de-contenedores-y-c\xf3mo-cilium-lo-usa-para-reemplazar-kube-proxy-por-qu\xe9-iptables-escala-mal",level:3},{value:"3. [Investigar] \xbfC\xf3mo funciona exactamente el DNS interno de Docker a nivel de implementaci\xf3n? \xbfQu\xe9 es <code>127.0.0.11</code> y c\xf3mo el daemon Docker intercepta las consultas DNS desde los contenedores?",id:"3-investigar-c\xf3mo-funciona-exactamente-el-dns-interno-de-docker-a-nivel-de-implementaci\xf3n-qu\xe9-es-1270011-y-c\xf3mo-el-daemon-docker-intercepta-las-consultas-dns-desde-los-contenedores",level:3},{value:"4. [Investigar] \xbfQu\xe9 son exactamente los IPvlan y Macvlan drivers en Docker y en qu\xe9 se diferencian? \xbfCu\xe1ndo usar\xedas cada uno?",id:"4-investigar-qu\xe9-son-exactamente-los-ipvlan-y-macvlan-drivers-en-docker-y-en-qu\xe9-se-diferencian-cu\xe1ndo-usar\xedas-cada-uno",level:3},{value:"5. [Conectar] La clase menciona la cadena DOCKER-USER en iptables. \xbfC\xf3mo implementar\xedas una whitelist de IPs para un puerto publicado sin que Docker sobreescriba tus reglas? Inclu\xed el enfoque con iptables y con Traefik/nginx como proxy reverso.",id:"5-conectar-la-clase-menciona-la-cadena-docker-user-en-iptables-c\xf3mo-implementar\xedas-una-whitelist-de-ips-para-un-puerto-publicado-sin-que-docker-sobreescriba-tus-reglas-inclu\xed-el-enfoque-con-iptables-y-con-traefiknginx-como-proxy-reverso",level:3},{value:"6. [Conectar] \xbfC\xf3mo funciona el hairpin NAT en Docker y por qu\xe9 <code>docker-proxy</code> existe como userland proxy?",id:"6-conectar-c\xf3mo-funciona-el-hairpin-nat-en-docker-y-por-qu\xe9-docker-proxy-existe-como-userland-proxy",level:3},{value:"7. [Conectar] \xbfC\xf3mo funciona el descubrimiento de servicios (service discovery) en una red overlay de Swarm? \xbfQu\xe9 diferencia hay con el de Kubernetes?",id:"7-conectar-c\xf3mo-funciona-el-descubrimiento-de-servicios-service-discovery-en-una-red-overlay-de-swarm-qu\xe9-diferencia-hay-con-el-de-kubernetes",level:3},{value:"8. [Cuestionar] &quot;IPv4 se est\xe1 agotando, los contenedores deber\xedan usar IPv6 por defecto&quot;. \xbfEst\xe1 Docker preparado para IPv6-first? \xbfCu\xe1les son los bloqueantes actuales?",id:"8-cuestionar-ipv4-se-est\xe1-agotando-los-contenedores-deber\xedan-usar-ipv6-por-defecto-est\xe1-docker-preparado-para-ipv6-first-cu\xe1les-son-los-bloqueantes-actuales",level:3},{value:"9. [Cuestionar] \xbfEs <code>--net=host</code> una mala pr\xe1ctica siempre o tiene casos de uso leg\xedtimos en producci\xf3n? \xbfQu\xe9 alternativas existen cuando necesit\xe1s rendimiento de red m\xe1ximo?",id:"9-cuestionar-es---nethost-una-mala-pr\xe1ctica-siempre-o-tiene-casos-de-uso-leg\xedtimos-en-producci\xf3n-qu\xe9-alternativas-existen-cuando-necesit\xe1s-rendimiento-de-red-m\xe1ximo",level:3},{value:"10. [Cuestionar] \xbfDeber\xedas usar siempre redes personalizadas (<code>docker network create</code>) en lugar de la red bridge default? \xbfHay alg\xfan caso donde la red default sea preferible?",id:"10-cuestionar-deber\xedas-usar-siempre-redes-personalizadas-docker-network-create-en-lugar-de-la-red-bridge-default-hay-alg\xfan-caso-donde-la-red-default-sea-preferible",level:3}];function t(e){const a={code:"code",h1:"h1",h3:"h3",header:"header",hr:"hr",p:"p",pre:"pre",strong:"strong",...(0,s.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(a.header,{children:(0,r.jsx)(a.h1,{id:"cuestionario-m06--redes-en-docker",children:"Cuestionario M06 \u2014 Redes en Docker"})}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Instrucci\xf3n"}),": Estas preguntas eval\xfaan si investigaste m\xe1s all\xe1 del\r\ncontenido de la clase. No alcanza con lo visto en ",(0,r.jsx)(a.code,{children:"clase.md"}),".\r\nFundament\xe1 tus respuestas con fuentes, autores o ejemplos concretos."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"1-investigar-c\xf3mo-funciona-exactamente-la-red-overlay-de-docker-swarm-usando-vxlan-describ\xed-el-encapsulamiento-de-paquetes-y-el-rol-del-plano-de-control-gossip-vs-plano-de-datos-vxlan",children:"1. [Investigar] \xbfC\xf3mo funciona exactamente la red overlay de Docker Swarm usando VXLAN? Describ\xed el encapsulamiento de paquetes y el rol del plano de control (gossip) vs plano de datos (VXLAN)."}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": VXLAN (Virtual eXtensible LAN, RFC 7348) encapsula tramas Ethernet L2 dentro de paquetes UDP (puerto 4789) sobre la red IP subyacente (underlay). En Swarm: 1) El contenedor env\xeda una trama Ethernet a su veth pair, 2) El bridge virtual del overlay recibe la trama, 3) Si la MAC destino est\xe1 en otro nodo, el driver overlay encapsula la trama en un paquete VXLAN con el VNI (Virtual Network Identifier) correspondiente a la red overlay, 4) El paquete se env\xeda al nodo destino por la red f\xedsica (underlay) usando la IP del host destino, 5) El nodo destino desencapsula y entrega la trama al contenedor. El plano de control (gossip protocol, puerto 7946) distribuye la tabla de mapeo MAC\u2192IP de nodo y las membres\xedas de red overlay a todos los nodos del cluster. El plano de datos (VXLAN, puerto 4789) transporta el tr\xe1fico real."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La arquitectura de networking de Swarm est\xe1 documentada en github.com/moby/libnetwork y en charlas de Madhu Venugopal (Docker networking lead). VXLAN fue elegido sobre GRE o STT porque: usa UDP (tratable por firewalls y load balancers est\xe1ndar), soporta hasta 16 millones de redes virtuales (VNI de 24 bits), y tiene soporte de hardware offloading (NICs modernos pueden encapsular/desencapsular VXLAN en hardware). El gossip usa SWIM (Scalable Weakly-consistent Infection-style Membership) para propagar estado de red entre nodos sin depender del manager central."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"2-investigar-qu\xe9-es-exactamente-ebpf-en-el-contexto-de-networking-de-contenedores-y-c\xf3mo-cilium-lo-usa-para-reemplazar-kube-proxy-por-qu\xe9-iptables-escala-mal",children:"2. [Investigar] \xbfQu\xe9 es exactamente eBPF en el contexto de networking de contenedores y c\xf3mo Cilium lo usa para reemplazar kube-proxy? \xbfPor qu\xe9 iptables escala mal?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Cilium usa eBPF para implementar load balancing en el kernel con complejidad O(1) usando mapas hash, en lugar del enfoque O(n) de kube-proxy con iptables. kube-proxy con iptables escala mal porque: cada Service crea m\xfaltiples reglas en las cadenas NAT/FILTER, y para cada paquete el kernel eval\xfaa secuencialmente todas las reglas (O(n) con n = n\xfamero de Services). Con 10,000 Services, un paquete puede atravesar 50,000+ reglas iptables, causando latencia y consumo de CPU del kernel. Cilium inserta programas eBPF en el kernel que implementan un lookup hash O(1) para resolver Service\u2192Endpoint, y manejan DNAT directamente en el kernel sin pasar por iptables. Adem\xe1s, eBPF puede inspeccionar hasta L7 (HTTP headers, gRPC) para aplicar pol\xedticas de red a nivel de API."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": Thomas Graf (Cilium co-creator, Isovalent) demostr\xf3 en m\xfaltiples benchmarks (KubeCon 2018, 2019) que iptables se degrada con miles de Services, mientras eBPF mantiene rendimiento constante. El problema de iptables es su dise\xf1o: cada regla es evaluada secuencialmente en una lista enlazada en el kernel. IPVS (otro modo de kube-proxy) mejora esto con hash O(1) para el backend selection, pero sigue usando iptables para el DNAT inicial. eBPF elimina completamente iptables del data path. Cilium es ahora un proyecto graduado de CNCF y el CNI por defecto en GKE Dataplane V2. La programabilidad de eBPF permite hacer operaciones que eran imposibles con iptables: inspecci\xf3n de tr\xe1fico HTTP/gRPC/Kafka, m\xe9tricas de latencia por API endpoint, y pol\xedticas de red basadas en identidad."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsxs)(a.h3,{id:"3-investigar-c\xf3mo-funciona-exactamente-el-dns-interno-de-docker-a-nivel-de-implementaci\xf3n-qu\xe9-es-1270011-y-c\xf3mo-el-daemon-docker-intercepta-las-consultas-dns-desde-los-contenedores",children:["3. [Investigar] \xbfC\xf3mo funciona exactamente el DNS interno de Docker a nivel de implementaci\xf3n? \xbfQu\xe9 es ",(0,r.jsx)(a.code,{children:"127.0.0.11"})," y c\xf3mo el daemon Docker intercepta las consultas DNS desde los contenedores?"]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Docker configura cada contenedor con un servidor DNS en ",(0,r.jsx)(a.code,{children:"127.0.0.11"})," (dentro del namespace de red del contenedor). Internamente, Docker crea una regla iptables (en la cadena OUTPUT del contenedor) que redirige el tr\xe1fico UDP/TCP puerto 53 con destino ",(0,r.jsx)(a.code,{children:"127.0.0.11"})," al daemon Docker en el host. El daemon Docker ejecuta un resolver DNS embebido (no un servidor DNS externo) que: 1) busca el nombre en su tabla interna (contenedores en la misma red con sus nombres y aliases), 2) si no lo encuentra, forwardea la consulta a los DNS servers configurados en el host (o los especificados con ",(0,r.jsx)(a.code,{children:"--dns"}),"). El resolver soporta round-robin: si m\xfaltiples contenedores comparten el mismo alias, devuelve las IPs en orden rotativo."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La implementaci\xf3n est\xe1 en github.com/moby/libnetwork (package ",(0,r.jsx)(a.code,{children:"resolvconf"})," y ",(0,r.jsx)(a.code,{children:"embedded DNS"}),"). El DNS embebido usa un servidor DNS interno (basado en ",(0,r.jsx)(a.code,{children:"miekg/dns"})," Go library) que mantiene un registro de todos los endpoints de red. Las consultas se forwardean a los DNS servers externos usando el mismo algoritmo que ",(0,r.jsx)(a.code,{children:"resolv.conf"})," (hasta 3 nameservers, timeout 5s). La regla iptables que redirige el tr\xe1fico DNS es: ",(0,r.jsx)(a.code,{children:"-t nat -A OUTPUT -d 127.0.0.11 -p udp --dport 53 -j DNAT --to-destination &#x3C;dockerd-ip>:&#x3C;port>"}),". Esto es transparente para el contenedor, que cree que habla con un DNS server normal en 127.0.0.11."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"4-investigar-qu\xe9-son-exactamente-los-ipvlan-y-macvlan-drivers-en-docker-y-en-qu\xe9-se-diferencian-cu\xe1ndo-usar\xedas-cada-uno",children:"4. [Investigar] \xbfQu\xe9 son exactamente los IPvlan y Macvlan drivers en Docker y en qu\xe9 se diferencian? \xbfCu\xe1ndo usar\xedas cada uno?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Macvlan asigna una MAC address virtual \xdaNICA a cada contenedor, haci\xe9ndolo aparecer como un dispositivo f\xedsico independiente en la red. IPvlan (m\xe1s moderno) asigna una IP \xfanica a cada contenedor pero comparte la misma MAC address del host (o una MAC virtual compartida entre todos los contenedores IPvlan). La diferencia principal es el consumo de MAC addresses (Macvlan necesita una por contenedor, IPvlan comparte) y la compatibilidad con switches de red (algunos switches limitan el n\xfamero de MACs por puerto). Macvlan se usa para aplicaciones legacy que requieren su propia identidad de red (MAC propia, IP propia, visible al DHCP del corporativo). IPvlan se usa en entornos cloud donde el hypervisor o switch virtual limita las MACs (AWS, Azure bloquean m\xfaltiples MACs por instancia EC2/VM, haciendo Macvlan inviable)."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La documentaci\xf3n del kernel Linux (Documentation/networking/ipvlan.txt) detalla los modos de IPvlan: L2 (bridge mode, contenedor aparece en la misma LAN), L3 (router mode, el host act\xfaa como router, los contenedores est\xe1n en subredes aisladas), y L3S (L3 + soporte para iptables/conntrack). Docker soporta Macvlan desde 1.12 y IPvlan es experimental/third-party. En AWS, el l\xedmite de 10 MACs por ENI hace Macvlan inviable, pero IPvlan L3 funciona. IPvlan L3 es \xfatil para escalar: miles de contenedores pueden compartir una sola MAC del host, eliminando la limitaci\xf3n de tabla MAC del switch."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"5-conectar-la-clase-menciona-la-cadena-docker-user-en-iptables-c\xf3mo-implementar\xedas-una-whitelist-de-ips-para-un-puerto-publicado-sin-que-docker-sobreescriba-tus-reglas-inclu\xed-el-enfoque-con-iptables-y-con-traefiknginx-como-proxy-reverso",children:"5. [Conectar] La clase menciona la cadena DOCKER-USER en iptables. \xbfC\xf3mo implementar\xedas una whitelist de IPs para un puerto publicado sin que Docker sobreescriba tus reglas? Inclu\xed el enfoque con iptables y con Traefik/nginx como proxy reverso."}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Con iptables, agreg\xe1s reglas en la cadena DOCKER-USER que se eval\xfaan ANTES que DOCKER. Ejemplo para restringir puerto 8080 a solo IP 10.0.0.5:"]}),"\n",(0,r.jsx)(a.pre,{children:(0,r.jsx)(a.code,{className:"language-bash",children:"iptables -I DOCKER-USER -p tcp --dport 8080 ! -s 10.0.0.5 -j DROP\r\niptables -I DOCKER-USER -p tcp --dport 8080 -s 10.0.0.5 -j RETURN\n"})}),"\n",(0,r.jsxs)(a.p,{children:["DOCKER-USER persiste entre reinicios del daemon. El enfoque con reverse proxy (recomendado para producci\xf3n): no publicar el puerto del contenedor con ",(0,r.jsx)(a.code,{children:"-p"})," (el contenedor solo expone en redes internas), y exponer un solo Traefik/nginx que haga proxy reverso con whitelist de IPs en su configuraci\xf3n."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": La cadena DOCKER-USER fue dise\xf1ada expl\xedcitamente para este prop\xf3sito. Docker eval\xfaa: DOCKER-USER \u2192 DOCKER \u2192 FORWARD. Las reglas en DOCKER-USER no son tocadas por Docker durante reinicios. La alternativa moderna (reverse proxy) es m\xe1s mantenible: Traefik tiene middleware ",(0,r.jsx)(a.code,{children:"ipWhiteList"}),", nginx tiene ",(0,r.jsx)(a.code,{children:"allow/deny"}),". La ventaja: reglas declarativas en YAML, m\xe9tricas, y TLS centralizado. La desventaja: overhead de proxy L7. Para casos simples, iptables con DOCKER-USER es m\xe1s eficiente (sin proxy intermedio). Para aplicaciones con tr\xe1fico HTTP/HTTPS, reverse proxy es la pr\xe1ctica recomendada."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsxs)(a.h3,{id:"6-conectar-c\xf3mo-funciona-el-hairpin-nat-en-docker-y-por-qu\xe9-docker-proxy-existe-como-userland-proxy",children:["6. [Conectar] \xbfC\xf3mo funciona el hairpin NAT en Docker y por qu\xe9 ",(0,r.jsx)(a.code,{children:"docker-proxy"})," existe como userland proxy?"]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Hairpin NAT (o NAT loopback) ocurre cuando un contenedor intenta acceder a un servicio publicado de otro contenedor usando la IP p\xfablica del host. El tr\xe1fico sale del contenedor, llega a la IP del host, y debe ser DNATeado de vuelta al contenedor destino. iptables puede manejar esto pero requiere ",(0,r.jsx)(a.code,{children:"route_localnet"})," y configuraciones espec\xedficas. ",(0,r.jsx)(a.code,{children:"docker-proxy"})," (userland proxy) existe como soluci\xf3n a este problema: es un proceso que escucha en el puerto publicado del host y forwardea conexiones al contenedor v\xeda la red Docker interna, sin pasar por iptables. Fue creado antes de que iptables soportara hairpin NAT confiablemente. Se puede deshabilitar con ",(0,r.jsx)(a.code,{children:"--userland-proxy=false"})," en daemon.json, confiando solo en iptables."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": El ",(0,r.jsx)(a.code,{children:"docker-proxy"})," fue una soluci\xf3n pragm\xe1tica de los primeros d\xedas de Docker (2013-2015) cuando el soporte de hairpin NAT en kernels era inconsistente. Hoy, iptables maneja hairpin correctamente en kernels modernos, y ",(0,r.jsx)(a.code,{children:"docker-proxy"})," es t\xe9cnicamente redundante. Sin embargo, sigue habilitado por defecto por compatibilidad. ",(0,r.jsx)(a.code,{children:"docker-proxy"})," agrega overhead (un proceso extra por cada puerto publicado, context switching userland\u2194kernel). Para rendimiento en producci\xf3n, se recomienda ",(0,r.jsx)(a.code,{children:"--userland-proxy=false"})," en el daemon. La cadena PREROUTING maneja el DNAT, y la cadena POSTROUTING maneja el SNAT/MASQUERADE de vuelta."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"7-conectar-c\xf3mo-funciona-el-descubrimiento-de-servicios-service-discovery-en-una-red-overlay-de-swarm-qu\xe9-diferencia-hay-con-el-de-kubernetes",children:"7. [Conectar] \xbfC\xf3mo funciona el descubrimiento de servicios (service discovery) en una red overlay de Swarm? \xbfQu\xe9 diferencia hay con el de Kubernetes?"}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": En Swarm: 1) Cada servicio obtiene una VIP (Virtual IP) estable, 2) El DNS interno resuelve el nombre del servicio a la VIP, 3) IPVS en el kernel balancea el tr\xe1fico de la VIP entre las IPs de las r\xe9plicas. En Kubernetes: 1) Cada Service obtiene un ClusterIP (VIP), 2) CoreDNS/kube-dns resuelve ",(0,r.jsx)(a.code,{children:"&#x3C;service>.&#x3C;namespace>.svc.cluster.local"})," al ClusterIP, 3) kube-proxy (iptables/IPVS) balancea el tr\xe1fico del ClusterIP a los endpoints (Pods). La diferencia principal: en Swarm la VIP es por servicio (cada servicio tiene su VIP que balancea entre r\xe9plicas). En K8s, los Pods tienen IPs \xfanicas en todo el cluster (cada Pod tiene IP propia, no NAT entre Pods), y el Service es una abstracci\xf3n arriba de esas IPs."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": Swarm usa VIP porque replica el modelo de red tradicional (los contenedores tienen IPs privadas en redes overlay con VXLAN). K8s usa Pod IPs porque la especificaci\xf3n CNI exige que cada Pod tenga IP \xfanica en todo el cluster y sea alcanzable sin NAT. Esto hace que el modelo de K8s sea m\xe1s simple para aplicaciones (la app ve su propia IP real) pero m\xe1s complejo para la red subyacente (el CNI debe implementar routing entre nodos sin overlay). Swarm es m\xe1s simple de implementar (VXLAN overlay universal), K8s es m\xe1s flexible (CNI pluggable que puede usar overlay, BGP, o L2)."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsx)(a.h3,{id:"8-cuestionar-ipv4-se-est\xe1-agotando-los-contenedores-deber\xedan-usar-ipv6-por-defecto-est\xe1-docker-preparado-para-ipv6-first-cu\xe1les-son-los-bloqueantes-actuales",children:'8. [Cuestionar] "IPv4 se est\xe1 agotando, los contenedores deber\xedan usar IPv6 por defecto". \xbfEst\xe1 Docker preparado para IPv6-first? \xbfCu\xe1les son los bloqueantes actuales?'}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": Docker tiene soporte para IPv6 desde Docker 1.5 (2015), pero NO est\xe1 habilitado por defecto y tiene limitaciones significativas: 1) Requiere configuraci\xf3n manual de subnet IPv6 en daemon.json (",(0,r.jsx)(a.code,{children:'"ipv6": true, "fixed-cidr-v6": "2001:db8:1::/64"'}),"), 2) El DNS embebido no soporta AAAA records por defecto (solo A), 3) Docker Compose no tiene soporte nativo para IPv6, 4) Docker Hub y la mayor\xeda de registries no tienen endpoints IPv6, 5) La red bridge default solo configura IPv4 (requiere ",(0,r.jsx)(a.code,{children:"docker network create --ipv6"}),"). En Kubernetes, IPv6-only clusters son soportados desde K8s 1.21 (dual-stack desde 1.20, GA en 1.23). Los bloqueantes son ecosistema (muchas im\xe1genes y herramientas asumen IPv4), no t\xe9cnicos."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),": El issue tracker de Docker (github.com/moby/moby) tiene issues abiertos desde 2016 sobre IPv6 support gaps. La postura de Docker (seg\xfan el CTO de Docker, comentado en varios issues) es que IPv6 es importante pero no prioritario porque la mayor\xeda de los usuarios despliegan en entornos IPv4 (cloud providers, redes corporativas). En K8s, el SIG-Network impuls\xf3 dual-stack a GA en 1.23, y Cilium soporta IPv6-only clusters. La realidad en 2025: la mayor\xeda de los deployments siguen siendo IPv4 o dual-stack, no IPv6-only. El agotamiento de IPv4 se mitiga con NAT masivo, no con migraci\xf3n a IPv6 en el corto plazo."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsxs)(a.h3,{id:"9-cuestionar-es---nethost-una-mala-pr\xe1ctica-siempre-o-tiene-casos-de-uso-leg\xedtimos-en-producci\xf3n-qu\xe9-alternativas-existen-cuando-necesit\xe1s-rendimiento-de-red-m\xe1ximo",children:["9. [Cuestionar] \xbfEs ",(0,r.jsx)(a.code,{children:"--net=host"})," una mala pr\xe1ctica siempre o tiene casos de uso leg\xedtimos en producci\xf3n? \xbfQu\xe9 alternativas existen cuando necesit\xe1s rendimiento de red m\xe1ximo?"]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": ",(0,r.jsx)(a.code,{children:"--net=host"})," elimina el aislamiento de red (el contenedor usa directamente el namespace de red del host). Es leg\xedtimo en casos espec\xedficos: 1) aplicaciones que requieren m\xe1ximo rendimiento de red (high-frequency trading, procesamiento de paquetes en espacio de kernel), 2) herramientas de monitoreo de red del host (ntop, Wireshark, cAdvisor), 3) aplicaciones que necesitan escuchar en muchos puertos din\xe1micos. NO es aceptable para servicios de aplicaci\xf3n generales porque: rompe el aislamiento (el contenedor puede interferir con la red del host), los puertos del contenedor y del host colisionan, y perd\xe9s todas las features de networking de Docker (DNS interno, redes personalizadas, NetworkPolicy en K8s). Alternativas: usar ",(0,r.jsx)(a.code,{children:"--network=macvlan"})," (IP propia en la red con rendimiento cercano a nativo) o Podman (que puede mapear puertos <1024 con CAP_NET_BIND_SERVICE sin host networking)."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': La documentaci\xf3n de Docker advierte "host networking is only available on Linux and should be used with caution". En t\xe9rminos de rendimiento, ',(0,r.jsx)(a.code,{children:"--net=host"})," es ~2-5% m\xe1s r\xe1pido que bridge (sin overhead de NAT, bridge, veth pair), pero este overhead es despreciable para la mayor\xeda de aplicaciones (API REST, web servers). Solo aplicaciones que procesan millones de paquetes por segundo (load balancers, proxies de alto rendimiento, DPI) se benefician. Cilium/eBPF con CNI chaining ofrece rendimiento cercano a host sin perder aislamiento, y es la alternativa moderna para alto rendimiento en K8s."]}),"\n",(0,r.jsx)(a.hr,{}),"\n",(0,r.jsxs)(a.h3,{id:"10-cuestionar-deber\xedas-usar-siempre-redes-personalizadas-docker-network-create-en-lugar-de-la-red-bridge-default-hay-alg\xfan-caso-donde-la-red-default-sea-preferible",children:["10. [Cuestionar] \xbfDeber\xedas usar siempre redes personalizadas (",(0,r.jsx)(a.code,{children:"docker network create"}),") en lugar de la red bridge default? \xbfHay alg\xfan caso donde la red default sea preferible?"]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Respuesta"}),": S\xed, siempre deber\xedas usar redes personalizadas en producci\xf3n y desarrollo. La red bridge default carece de: 1) resoluci\xf3n DNS entre contenedores (solo por IP), 2) aislamiento (todos los contenedores conectados a la default pueden comunicarse entre s\xed sin restricciones), 3) configuraci\xf3n de subnet y gateway (Docker asigna autom\xe1ticamente sin tu control). El \xfanico caso donde la red default podr\xeda ser preferible es en scripts de una l\xednea o demos m\xednimas donde no necesit\xe1s comunicaci\xf3n entre contenedores, o en entornos extremadamente restringidos donde no pod\xe9s crear recursos adicionales. Incluso para desarrollo, una red personalizada es mejor porque permite que los contenedores se comuniquen por nombre."]}),"\n",(0,r.jsxs)(a.p,{children:[(0,r.jsx)(a.strong,{children:"Por qu\xe9"}),': La red bridge default es b\xe1sicamente legacy behavior mantenido por compatibilidad hacia atr\xe1s. Docker mismo recomienda en su documentaci\xf3n: "User-defined bridges provide better isolation and interoperability between containers." En Compose, Docker crea autom\xe1ticamente una red personalizada por proyecto, que es mucho mejor que la default. La diferencia m\xe1s pr\xe1ctica que los desarrolladores notan: ',(0,r.jsx)(a.code,{children:"docker run --network mynet --name db postgres"})," y ",(0,r.jsx)(a.code,{children:"docker run --network mynet --name app myapp"})," pueden comunicarse usando ",(0,r.jsx)(a.code,{children:"db"})," como hostname. En la red default, ",(0,r.jsx)(a.code,{children:"app"})," debe conocer la IP de ",(0,r.jsx)(a.code,{children:"db"})," (que cambia cada vez que se recrea)."]})]})}function u(e={}){const{wrapper:a}={...(0,s.R)(),...e.components};return a?(0,r.jsx)(a,{...e,children:(0,r.jsx)(t,{...e})}):t(e)}},28453(e,a,n){n.d(a,{R:()=>i,x:()=>d});var o=n(96540);const r={},s=o.createContext(r);function i(e){const a=o.useContext(s);return o.useMemo(function(){return"function"==typeof e?e(a):{...a,...e}},[a,e])}function d(e){let a;return a=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:i(e.components),o.createElement(s.Provider,{value:a},e.children)}}}]);